#!/usr/bin/env python3
import base64, os, sys

_SCRIPT_B64 = """"""
_CSV_B64 = """"""

with open("quant_eval.py.py", "wb") as f:
    f.write(base64.b64decode(_SCRIPT_B64))
with open("tensors.csv", "wb") as f:
    f.write(base64.b64decode(_CSV_B64))

hf_token_path = "/kaggle/input/datasets/deepresearch1a10/hf-token-store/hf_token.txt"
if os.path.isfile(hf_token_path):
    try:
        with open(hf_token_path) as f:
            os.environ["HF_TOKEN"] = f.read().strip()
        print("[run] HF_TOKEN loaded from dataset", flush=True)
    except Exception as e:
        print(f"[run] could not read HF token: {e}", file=sys.stderr)

sys.argv = [
    "quant_eval.py.py", "evaluate",
    "--model", "LiquidAI/LFM2.5-230M-Base",
    "--allowlist", "tensors.csv",
    "--out-dir", "./results",
    "--hf-repo", "w-ahmad/Quant-study",
]
print("[run] executing:", " ".join(sys.argv), flush=True)

ns = {"__name__": "__main__", "__file__": "quant_eval.py.py"}
exec(compile(base64.b64decode(_SCRIPT_B64), "quant_eval.py.py", "exec"), ns)
